<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { useRouter } from 'vue-router'
import AdminLayout from '../../layouts/AdminLayout.vue'
import QRCodeDisplay from '../../components/QRCodeDisplay.vue'
import api from '../../services/api'

const route = useRoute(); const router = useRouter(); const copied = ref(false); const actionMessage = ref(''); const actionError = ref(false); const loading = ref(true); const event = ref(null)
const link = computed(() => event.value?.registration_link || `${window.location.origin}/events/${route.params.id}/register`)
const copyLink = async () => { await navigator.clipboard?.writeText(link.value); copied.value = true; setTimeout(() => { copied.value = false }, 1800) }
const downloadQr = () => { const canvas = document.querySelector('.event-detail-qr canvas'); if (!canvas) return; const anchor = document.createElement('a'); anchor.download = `${event.value?.name || 'event'}-qr.png`; anchor.href = canvas.toDataURL('image/png'); anchor.click() }
const dateLabel = computed(() => event.value?.start_date ? new Date(`${event.value.start_date}T00:00:00`).toLocaleDateString(undefined, { month: 'long', day: 'numeric', year: 'numeric' }) : 'Date to be confirmed')
const shareEvent = async () => { if (navigator.share) await navigator.share({ title: event.value?.name, url: link.value }); else await copyLink() }
const updateEventStatus = async (action, message) => { if (action === 'cancel' && !window.confirm('Cancel this event? It will remain in the database but will no longer be active.')) return; actionError.value = false; try { await api.patch(`/admin/events/${event.value.id}/${action}`); event.value = { ...event.value, status: action === 'close' ? 'closed' : 'cancelled' }; const list = JSON.parse(localStorage.getItem('event_list') || '[]'); const item = list.find((entry) => String(entry.id) === String(event.value.id)); if (item) item.status = event.value.status; localStorage.setItem('event_list', JSON.stringify(list)); actionMessage.value = message } catch (requestError) { actionError.value = true; actionMessage.value = requestError.response?.data?.message || `Unable to ${action} this event. Check your admin session and API connection.` } setTimeout(() => { actionMessage.value = ''; actionError.value = false }, 3000) }
const exportRegistrants = () => router.push(`/admin/events/${event.value.id}/registrants`)
const normalizeEvent = (item, registered = 0) => ({ ...item, status: item.status === 'published' ? 'open' : item.status, registered: item.registered ?? registered, maximum_participants: item.maximum_participants ?? item.capacity, start_date: item.start_date || item.starts_at?.slice(0, 10), start_time: item.start_time || item.starts_at?.slice(11, 16), end_time: item.end_time || item.ends_at?.slice(11, 16), registration_link: item.registration_link || `${window.location.origin}/events/${item.id}/register` })
const loadEvent = async () => { try { const { data } = await api.get(`/events/${route.params.id}`); event.value = normalizeEvent(data.data, data.registered) } catch { const local = JSON.parse(localStorage.getItem('event_list') || '[]').find((item) => String(item.id) === String(route.params.id)); event.value = local || null } finally { loading.value = false } }
onMounted(loadEvent)
</script>

<template><AdminLayout><section v-if="event" class="event-detail-workspace"><RouterLink class="back-link" to="/admin/events">← All events</RouterLink><header class="detail-workspace-heading"><div><div class="detail-title-row"><p class="admin-eyebrow">Event workspace</p><span class="event-status" :class="event.status">{{ event.status === 'open' ? 'Published' : event.status }}</span></div><h1>{{ event.name }}</h1><p>{{ event.description || 'Manage your event, registration experience, and attendee activity.' }}</p></div><div class="detail-heading-actions"><a class="secondary-button" :href="link" target="_blank">Preview</a><RouterLink class="secondary-button" :to="`/admin/events/${event.id}/edit`">Edit event</RouterLink></div></header><div v-if="actionMessage" class="detail-action-message">{{ actionMessage }}</div><section class="event-action-grid"><a :href="link" target="_blank"><span>👁</span><strong>Preview</strong><small>See attendee view</small></a><button type="button" @click="copyLink"><span>🔗</span><strong>{{ copied ? 'Copied' : 'Copy registration link' }}</strong><small>Share the event URL</small></button><a href="#qr"><span>📱</span><strong>View QR code</strong><small>Open event QR</small></a><RouterLink :to="`/admin/events/${event.id}/edit`"><span>✏️</span><strong>Edit event</strong><small>Update event details</small></RouterLink><RouterLink :to="`/admin/events/${event.id}/edit?step=4`"><span>📋</span><strong>Manage registration form</strong><small>Edit attendee fields</small></RouterLink><RouterLink :to="`/admin/events/${event.id}/registrants`"><span>👥</span><strong>View registrants</strong><small>Review attendees</small></RouterLink><RouterLink to="/admin/check-ins"><span>✅</span><strong>Check-in participants</strong><small>Scan attendee passes</small></RouterLink><a href="#stats"><span>📊</span><strong>View statistics</strong><small>Registration overview</small></a><button type="button" @click="exportRegistrants"><span>📥</span><strong>Export registrants</strong><small>Download CSV</small></button><button type="button" :disabled="event.status === 'closed'" @click="updateEventStatus('close', 'Registration closed.')"><span>⏸</span><strong>Close registration</strong><small>Stop new sign-ups</small></button><button type="button" @click="shareEvent"><span>📢</span><strong>Share event</strong><small>Use device sharing</small></button><button type="button" class="danger-action" @click="updateEventStatus('cancel', 'Event cancelled.')"><span>🗑</span><strong>Cancel event</strong><small>Mark event cancelled</small></button></section><div class="detail-content-grid"><main><article id="stats" class="detail-panel"><header><div><p class="admin-eyebrow">At a glance</p><h2>Registration overview</h2></div><span class="detail-date">{{ dateLabel }}</span></header><div class="detail-stat-grid"><div><small>Registered</small><strong>{{ event.registered || 0 }}</strong><span>participants</span></div><div><small>Capacity</small><strong>{{ event.maximum_participants || '∞' }}</strong><span>maximum</span></div><div><small>Checked in</small><strong>0</strong><span>attendees</span></div><div><small>Completion rate</small><strong>—</strong><span>not enough data</span></div></div><div class="detail-event-info"><div><small>WHEN</small><strong>{{ dateLabel }} · {{ event.start_time || 'Time pending' }} – {{ event.end_time || '—' }}</strong></div><div><small>WHERE</small><strong>{{ event.location || 'Location pending' }}</strong></div><div><small>FORMAT</small><strong>{{ event.mode || 'In person' }}</strong></div></div></article><article class="detail-panel recent-panel"><header><div><p class="admin-eyebrow">Live activity</p><h2>Recent registrations</h2></div><RouterLink :to="`/admin/events/${event.id}/registrants`">View all attendees →</RouterLink></header><div class="recent-empty"><span>♧</span><div><strong>No registrations yet</strong><p>New attendees will appear here once they complete the registration form.</p></div></div></article></main><aside id="qr" class="event-detail-qr"><p class="admin-eyebrow">Share your event</p><h2>Registration QR code</h2><QRCodeDisplay :value="link" /><p class="qr-help">Scan to open the attendee registration page.</p><div class="detail-share-link"><small>Registration link</small><strong>{{ link }}</strong><button type="button" @click="copyLink">{{ copied ? 'Copied' : 'Copy link' }}</button></div><button type="button" class="qr-download" @click="downloadQr">↓ Download QR code</button></aside></div></section><section v-else class="event-empty-state"><div class="empty-icon">?</div><h3>Event not found</h3><p>This event may have been removed or is still being created.</p><RouterLink class="primary-button" to="/admin/events">Back to events</RouterLink></section></AdminLayout></template>
